import {state as appState} from './data.js';
import {recordActions,archiveView} from './management.js';
import {inbox} from './engagement.js';
import {can} from './access.js';
import {inventoryView,balanceControls,fileLink,photo} from './editors.js';
import {colour,productImage} from './core.js';
import {E,money,icon,button,link,field,select,textarea,checkbox,table,stat,badge,notice,empty,heading,tabs,previewBar,wordmark,mobileNav} from './ui.js';
import {popupEditor,reviewsAdmin,ownerAssistantView} from './commerce.js';
import {adminNav,seoModules} from './data.js';
import {available,profitStatement,demoReport} from './core.js';
import {seoView,settingsView,contentEditor,bannerEditor,teamView} from './configuration.js';
const edit=(type,id,label='View')=>recordActions(appState,type,id);
const exportBtn=type=>button(icon('download')+'Export CSV','export',`data-type="${type}"`,'btn secondary');
const newBtn=(type,label)=>button(icon('plus')+label,'new-record',`data-type="${type}"`);
const filterBar=(type,placeholder='Search records…',statuses=[])=>`<div class="toolbar"><input type="search" data-table-search="${type}" placeholder="${E(placeholder)}" aria-label="Search records">${statuses.length?`<select data-table-status="${type}" aria-label="Filter status"><option value="">All statuses</option>${statuses.map(x=>`<option>${E(x)}</option>`).join('')}</select>`:''}<span class="spacer"></span><span class="small muted">Demo records</span></div>`;
export function adminShell(content,s,path){const current=path.split('/')[2]||'overview',role=s.previewRole||'Super Admin';let nav=adminNav.filter(([id])=>can(s,id));return `${previewBar()}<div class="admin-shell"><aside class="admin-sidebar ${s.adminMenu?'open':''}"><a class="admin-logo" href="#/admin">${wordmark()}</a><nav aria-label="Admin navigation">${nav.map(([id,label,i],index)=>`${[0,3,8,13,16].includes(index)?`<div class="nav-label">${index===0?'Workspace':index===3?'Operations':index===8?'Finance':index===13?'Growth':'Administration'}</div>`:''}<a href="#/admin${id==='overview'?'':'/'+id}" class="${current===id||(current==='banners'&&id==='coupons')?'active':''}">${icon(i)}${label}</a>`).join('')}</nav><div class="admin-profile"><span class="avatar">AD</span><div>Demo Admin<small class="muted" style="display:block">${E(role)}</small></div></div></aside><div class="admin-main"><header class="admin-topbar"><div class="flex">${button(icon('menu'),'admin-menu','','icon-btn mobile-menu-btn')}<span class="muted">Admin</span><span>/</span><span>${E(adminNav.find(x=>x[0]===current)?.[1]||current.replace(/^./,c=>c.toUpperCase()))}</span></div><div class="flex"><input class="search-control" type="search" placeholder="Find a module…" aria-label="Find an admin module" id="admin-search">${link('Archived records','/admin/archive','text-link desktop-only')}${button(icon('bell'),'notifications','','icon-btn')}<span class="avatar">AD</span></div></header><main id="main" class="admin-content page-enter">${content}<div class="preview-foot">AELVO · FRONTEND PREVIEW · SAMPLE DATA</div></main></div></div>${mobileNav(true,path,s)}`}
function dashboard(s){const active=s.orders.filter(o=>!['Delivered','Cancelled'].includes(o.status));return `${heading('Overview','A clear view of your store, today.',link(icon('plus')+'Manual sale','/admin/manual')+link('Visit storefront','/','btn secondary'))}<div class="stats">${stat('Sample order value',money(s.orders.reduce((a,o)=>a+o.total,0)),'Across '+s.orders.length+' orders','bag')}${stat('Active orders',active.length,'Confirmation through delivery','truck')}${stat('Available funds',money(Object.values(s.accounts).reduce((a,b)=>a+b,0)),'Cash, bank and wallets','wallet')}${stat('Courier receivable',money(42000),'Separate from available funds','card',true)}</div><div class="admin-grid"><div class="card"><div class="between"><h3>Sales snapshot</h3><span class="small muted">Last 7 sample days</span></div><div class="legend"><span>Recognized sales</span></div><div class="chart">${[40,62,36,77,58,92,68].map((v,i)=>`<div class="bar-wrap"><div class="chart-bar" style="height:${v}%" title="${money(v*100)}"></div><span class="bar-label">${['Thu','Fri','Sat','Sun','Mon','Tue','Wed'][i]}</span></div>`).join('')}</div><div class="chart-labels"></div></div><div class="card"><h3>Needs your attention</h3>${[['Advance payments','1 review waiting','/admin/payments/advances'],['Low stock','1 variant below threshold','/admin/inventory'],['Courier settlement','৳50 variance to reconcile','/admin/payments/settlement'],['Returns','1 inspection passed','/admin/returns']].map(([a,b,url])=>link(`<div><strong>${a}</strong><p class="small muted">${b}</p></div>${icon('chevron')}`,url,'list-link')).join('')}</div></div><div class="between mb"><h3>Recent orders</h3>${link('View all orders','/admin/orders','text-link')}</div>${orderTable(s.orders.slice(0,5))}<div class="module-grid mt"><div class="module-card"><h3>Quick entry</h3>${link('New purchase','/admin/purchases','list-link')}${link('Stock movement','/admin/inventory','list-link')}${link('Add an expense','/admin/accounts/expenses','list-link')}</div><div class="module-card"><h3>Store health</h3><div class="status-line">Products ${badge(s.products.length+' active')}</div><div class="status-line">SMS provider ${badge('Not connected','outline')}</div><div class="status-line">Payment gateway ${badge('Not connected','outline')}</div></div><div class="module-card"><h3>Review a role</h3><p class="small muted mb">Preview the screens available to a staff role.</p><select id="preview-role" aria-label="Preview role"><option>Super Admin</option><option>Entry Staff</option><option>SEO Manager</option></select></div></div>`}
function orderTable(rows){rows=rows.filter(r=>!r.archived);return table(['Order','Customer','Date','Status','Payment','Total',''],rows.map(o=>[`<strong>${E(o.id)}</strong><p class="small muted">${E(o.source)}</p>`,E(o.customer),o.date,badge(o.status),`<span>${money(o.paid)} paid</span><p class="small muted">${money(o.total-o.paid)} remaining</p>`,money(o.total),recordActions(appState,'orders',o.id)]),'Amounts are illustrative. Uploaded payment proof alone is not paid.');}
function orders(s,id){if(id){const o=s.orders.find(x=>x.id===id);if(!o)return empty('Order not found','Check the order number.','/admin/orders','Back to orders');return `${heading(o.id,o.date+' · '+o.source+' order',button('Print','print','','btn secondary')+button('Update status','order-status',`data-id="${o.id}"`))}<div class="two-col"><div class="stack"><div class="card no-pad"><div class="card-title"><h3>Order items</h3>${badge(o.status)}</div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Price</th></tr></thead><tbody>${o.items.map(r=>{const p=s.products.find(p=>p.id===r.id);return `<tr><td><div class="flex"><img class="mini-image" src="${E(productImage(p,r.color))}" alt=""><div>${E(p.name)}<p class="small muted">${E(colour(p,r.color).name+' · '+r.size)}</p></div></div></td><td>${r.qty}</td><td>${money(p.price*r.qty)}</td></tr>`}).join('')||'<tr><td colspan="3">Earlier sample order · item breakdown unavailable</td></tr>'}</tbody></table></div></div><div class="card"><h3>Payments & balance</h3><div class="summary-line"><span>Order total</span><strong>${money(o.total)}</strong></div><div class="summary-line"><span>Verified payments</span><strong>${money(o.paid)}</strong></div><div class="summary-line total"><span>Remaining COD</span><strong>${money(o.total-o.paid)}</strong></div>${notice('Only verified payments reduce the courier COD amount.')}<div class="mt">${button('Record demo payment','order-payment',`data-id="${o.id}"`,'btn secondary')}</div></div><div class="card"><h3>Activity</h3><div class="timeline"><div class="timeline-step"><span class="timeline-dot"></span><div>Order created<p>${o.date}</p></div></div><div class="timeline-step"><span class="timeline-dot"></span><div>${E(o.status)}<p>Current sample workflow state</p></div></div></div></div></div><aside class="stack"><div class="card"><h3>Customer</h3><strong>${E(o.customer)}</strong><p class="small muted mt">${E(o.phone)}<br>${E(o.address)}</p></div><div class="card"><h3>Courier</h3><div class="status-line">Consignment ${badge(o.courier)}</div><div class="status-line">COD to collect <strong>${money(o.total-o.paid)}</strong></div><div class="mt">${button(o.courier==='Not booked'?'Preview booking':'View tracking',o.courier==='Not booked'?'courier-book':'track-order',`data-id="${o.id}"`,'btn secondary full')}</div><p class="form-help">Booking and delivery are separate events. No courier API is called.</p></div><div class="card"><h3>Internal note</h3><form data-form="order-note" data-id="${o.id}">${textarea('Note','note',o.note||'')}<button class="btn small secondary">Save note</button></form></div></aside></div>`;}return `${heading('Orders','Manage online and manual orders.',exportBtn('orders')+link('New manual sale','/admin/manual'))}<div class="stats">${stat('All orders',s.orders.length,'Sample register','bag')}${stat('Processing',s.orders.filter(o=>o.status==='Processing').length,'Ready for next steps','box')}${stat('In transit',s.orders.filter(o=>o.status==='In Transit').length,'With courier','truck')}${stat('Delivered',s.orders.filter(o=>o.status==='Delivered').length,'Fulfilment completed','check')}</div>${filterBar('orders','Search order or customer…',['Pending','Processing','In Transit','Delivered','Failed Delivery'])}<div data-filter-table="orders">${orderTable(s.orders)}</div>`}
function manual(s){const total=s.manual.reduce((n,r)=>n+s.products.find(p=>p.id===r.id).price*r.qty,0);return `${heading('Manual Sales','Create a walk-in sale or save it as a draft.',button('Clear sale','manual-clear','','btn secondary'))}<div class="two-col"><div><div class="toolbar"><input type="search" id="manual-search" placeholder="Find a product…" aria-label="Find a product"></div><div class="product-grid" id="manual-products">${s.products.filter(r=>!r.archived).map(p=>`<div class="card" style="padding:15px"><img src="${E(productImage(p))}" style="height:130px;object-position:70%" alt="${E(p.name)}"><h3 class="mt" style="font-size:14px">${E(p.name)}</h3><p class="small mb">${money(p.price)}</p>${button('Choose variant','manual-add',`data-id="${p.id}"`,'btn small secondary full')}</div>`).join('')}</div><div class="card mt"><h3>Sale items</h3>${s.manual.length?table(['Item','Size','Quantity','Amount',''],s.manual.map((r,i)=>{const p=s.products.find(p=>p.id===r.id);return [E(p.name),E(r.size),r.qty,money(p.price*r.qty),button('Remove','manual-remove',`data-index="${i}"`,'text-link')]})):notice('Choose products to start a sale.')}</div></div><form class="card summary" data-form="manual-sale"><h3>Payment</h3>${field('Customer (optional)','customer','','text','placeholder="Walk-in customer"')}${select('Payment account','account',Object.keys(s.accounts),'Cash')}${field('Cash / amount received','received',total||'','number','min="0" step="0.01" required')}${field('Order discount','discount','0','number',`min="0" max="${total}" step="0.01"`)}<div class="summary-line"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="summary-line"><span>Change</span><strong id="manual-change">${money(0)}</strong></div><div class="error-text" data-error></div><div class="stack mt"><button class="btn" name="intent" value="complete" ${!s.manual.length?'disabled':''}>Complete demo sale</button><button class="btn secondary" name="intent" value="draft" ${!s.manual.length?'disabled':''}>Save draft</button></div><p class="form-help">Drafts do not change stock or money. Completion updates only this preview’s sample records.</p></form></div>`}
function products(s){return `${heading('Products','Catalogue, variants and stock visibility.',exportBtn('products')+newBtn('products','Add product'))}${filterBar('products','Search product or category…',['Active','Draft'])}<div data-filter-table="products">${table(['Product','Category','Price','Cost','Available','Status',''],s.products.filter(r=>!r.archived).map(p=>[`<div class="flex"><img class="mini-image" src="${E(productImage(p))}" alt=""><div><strong>${E(p.name)}</strong><p class="small muted">${p.id}</p></div></div>`,E(p.category),money(p.price),money(p.cost),p.variants.reduce((a,v)=>a+v.onHand-v.reserved,0),badge(p.status),edit('products',p.id,'Edit')]))}</div><div class="notice mt">Stock is managed through the inventory ledger. Editing product details does not overwrite quantities.</div>`}
function inventory(s,tab){let rows=s.products.flatMap(p=>p.variants.map(v=>[E(p.name),E(v.size),v.onHand,v.reserved,v.onHand-v.reserved,badge(v.onHand-v.reserved<=10?'Low stock':'Available'),button('Movement','inventory-history',`data-id="${p.id}" data-size="${E(v.size)}"`,'text-link')]));let on=s.products.reduce((a,p)=>a+p.variants.reduce((b,v)=>b+v.onHand,0),0),reserved=s.products.reduce((a,p)=>a+p.variants.reduce((b,v)=>b+v.reserved,0),0);return `${heading('Inventory','Stock at variant level, with a clear movement history.',exportBtn('inventory')+newBtn('stock','Stock entry'))}<div class="stats">${stat('On hand',on,'Physical stock','box')}${stat('Reserved',reserved,'Committed to open orders','bag')}${stat('Available',on-reserved,'Sellable after reservations','layers')}${stat('Low-stock variants',rows.filter(r=>r[4]<=10).length,'At or below 10 units','info')}</div>${tabs([['','Stock overview'],['movements','Movement history']],tab||'','/admin/inventory/')}<div data-filter-table="inventory">${tab==='movements'?table(['Reference','Product','Type','Quantity','Source','Date'],s.records.movements.map(m=>[m.id,E(m.product),E(m.type),m.qty,E(m.reference),m.date])):filterBar('inventory','Search product or variant…')+table(['Product','Variant','On hand','Reserved','Available','Status',''],rows)}</div>`}
function purchases(s){return `${heading('Purchases','Keep supplier payments and stock receipts separate.',exportBtn('purchases')+newBtn('purchases','New purchase'))}<div class="stats">${stat('Purchase value',money(s.records.purchases.reduce((a,p)=>a+p.total,0)),'Across sample purchases','cart')}${stat('Paid',money(s.records.purchases.reduce((a,p)=>a+p.paid,0)),'Verified supplier payments','wallet')}${stat('Outstanding',money(s.records.purchases.reduce((a,p)=>a+p.total-p.paid,0)),'Supplier payable','file')}${stat('Awaiting receipt',s.records.purchases.filter(p=>p.status!=='Received').length,'Receiving is independent','truck')}</div>${filterBar('purchases','Search purchase or supplier…')}<div data-filter-table="purchases">${table(['Purchase','Supplier','Total','Paid','Due','Receiving','Slip',''],s.records.purchases.filter(r=>!r.archived).map(p=>[p.id,E(p.supplier),money(p.total),money(p.paid),money(p.total-p.paid),badge(p.status),fileLink(p.slip),edit('purchases',p.id)]))}</div>`}
function suppliers(s){return `${heading('Suppliers','Contacts, purchases and outstanding balances.',newBtn('suppliers','Add supplier'))}${filterBar('suppliers','Search suppliers…')}<div data-filter-table="suppliers">${table(['Supplier','Phone','Outstanding','Status',''],s.records.suppliers.filter(r=>!r.archived).map(p=>[`<strong>${E(p.name)}</strong><p class="small muted">${p.id}</p>`,E(p.phone),money(p.due),badge(p.status),edit('suppliers',p.id)]))}</div>`}
function customers(s,id){if(id==='risk')return `${heading('Customer Risk Review','Review evidence before changing an order or account.',link('Customers','/admin/customers','btn secondary'))}<div class="two-col"><div class="card"><div class="between"><h3>RV-0008 · Possible duplicate</h3>${badge('Review pending')}</div>${table(['Evidence','AEL-1040','AEL-1041'],[['Placed','10:05','10:09'],['Phone','01XXX XX3344','01XXX XX3344'],['Item','Grid Runner · White / 42','Grid Runner · White / 42'],['Quantity','1','1'],['Total',money(5990),money(5990)],['Checkout OTP','Verified','Verified'],['Browser / session','Unavailable','Unavailable']])}<div class="notice mt">Similarity is a review signal. Both orders remain active until an authorized decision is applied.</div></div><form class="card" data-form="risk-review"><h3>Review decision</h3>${select('Action','action',['Keep both orders','Flag for follow-up','Require advance','Disable COD','Clear flag'])}${textarea('Reason','reason','','required')}${checkbox('I reviewed the available evidence.','reviewed')}<button class="btn full mt">Save demo review</button><p class="form-help">No external risk lookup or real customer restriction is performed.</p></form></div>`;const c=s.records.customers.find(c=>c.id===id);if(c)return `${heading(c.name,c.id+' · '+c.type,button('Add internal note','customer-note',`data-id="${c.id}"`,'btn secondary'))}<div class="two-col"><div><div class="stats">${stat('Orders',c.orders,'Sample customer history','bag')}${stat('Delivered',c.delivered,'Successful deliveries','check')}</div>${table(['Order','Status','Total','Verified paid',''],s.orders.filter(o=>o.customer===c.name).map(o=>[o.id,badge(o.status),money(o.total),money(o.paid),link('View','/admin/orders/'+o.id,'text-link')]))}</div><div class="card"><h3>Customer details</h3><p>${E(c.name)}</p><p class="small muted mt">${E(c.phone)}<br>${E(c.type)}</p><div class="mt">${badge(c.status)}</div><p class="form-help mt">Account verification and a guest’s checkout verification have different scopes.</p>${c.note?`<hr class="divider"><h3>Internal note</h3><p class="small">${E(c.note)}</p>`:''}</div></div>`;return `${heading('Customers','Accounts, guests and customer history.',link('Risk review','/admin/customers/risk','btn secondary')+newBtn('customers','Add customer'))}${filterBar('customers','Search name or phone…')}<div data-filter-table="customers">${table(['Customer','Type','Orders','Delivered','Status',''],s.records.customers.filter(r=>!r.archived).map(c=>[`<strong>${E(c.name)}</strong><p class="small muted">${E(c.phone)}</p>`,E(c.type),c.orders,c.delivered,badge(c.status),recordActions(s,'customers',c.id)]))}</div>`}
function accounts(s,tab='overview'){const tabsHTML=tabs([['overview','Overview'],['ledger','Cash / Bank'],['expenses','Expenses']],tab,'/admin/accounts/');if(tab==='expenses')return `${heading('Expenses','Posted costs and drafts, kept separate.',exportBtn('expenses')+newBtn('expenses','New expense'))}${tabsHTML}<div class="stats">${stat('Posted expenses',money(s.records.expenses.filter(e=>e.status==='Posted').reduce((a,e)=>a+e.amount,0)),'Sample expense records','wallet')}${stat('Drafts',s.records.expenses.filter(e=>e.status==='Draft').length,'Not posted','file')}</div>${filterBar('expenses','Search category or account…')}<div data-filter-table="expenses">${table(['Reference','Category','Date','Account','Amount','Status',''],s.records.expenses.filter(r=>!r.archived).map(e=>[e.id,E(e.category),e.date,E(e.account),money(e.amount),badge(e.status),edit('expenses',e.id)]))}</div>`;return `${heading(tab==='ledger'?'Cash / Bank':'Accounts','Available funds and settlement balances.',button('Transfer','transfer','','btn secondary')+button('Add funds','add-funds'))}${tabsHTML}<div class="stats">${stat('Cash',money(s.accounts.Cash),'Available','wallet')}${stat('Bank',money(s.accounts.Bank),'Available','card')}${stat('Mobile wallets',money(s.accounts.bKash+s.accounts.Nagad+s.accounts.Rocket),'Available','card')}${stat('Settlement pending',money(48000),'Courier ৳42,000 + gateway ৳6,000','truck',true)}</div>${tab==='ledger'?`<div class="card"><div class="between mb"><h3>Bank ledger</h3>${badge('Sample opening period')}</div>${table(['Reference','Description','In','Out','Balance'],[['OPEN','Opening balance','—','—',money(136800)],['FUND-01','Owner funds',money(20000),'—',money(156800)],['PAY-42','Supplier payment','—',money(30000),money(126800)],['EXP-003','Utilities','—',money(1800),money(125000)]])}${notice('This opening ledger is a fixed sample. New demo movements appear in the audit log.')}</div>`:`<div class="admin-grid"><div class="card"><h3>Financial accounts</h3>${Object.entries(s.accounts).map(([k,v])=>`<div class="status-line"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}<div class="status-line"><strong>Total available</strong><strong>${money(Object.values(s.accounts).reduce((a,b)=>a+b,0))}</strong></div></div><div class="card"><h3>Receivables & payables</h3><div class="status-line">Courier receivable <strong>${money(42000)}</strong></div><div class="status-line">Gateway pending <strong>${money(6000)}</strong></div><div class="status-line">Supplier payable <strong>${money(53200)}</strong></div><div class="notice mt">Unremitted collections are separate from spendable cash.</div></div></div>`}`}
function payments(s,tab='transactions'){const t=tabs([['transactions','Transactions'],['advances','Advance review'],['settlement','Courier settlement']],tab,'/admin/payments/');if(tab==='advances'){const p=s.records.payments.find(p=>p.id==='REQ-0102');return `${heading('Advance Payment Review','Verify the transaction before reducing the order balance.')}${t}<div class="two-col"><div class="card"><div class="between"><h3>REQ-0102 · AEL-1026</h3>${badge(p?.status||'Review required')}</div><div class="status-line">Order total<strong>${money(3500)}</strong></div><div class="status-line">Required advance<strong>${money(700)}</strong></div><div class="status-line">Submitted method<strong>bKash</strong></div><div class="status-line">Reference<strong>DEMO-REFERENCE</strong></div><div class="upload-tile mt">${icon('image')}<p>Customer payment proof</p><small>Illustrative attachment slot</small></div><div class="notice mt">A customer reference or uploaded image is not payment confirmation.</div></div><form class="card" data-form="advance-review"><h3>Merchant verification</h3>${select('Decision','decision',['Verify received payment','Reject submission'])}${field('Merchant transaction reference','reference','','text','required placeholder="DEMO-MERCHANT-REF"')}${textarea('Note','note')}${checkbox('I checked the demo merchant evidence.','checked')}<div class="summary-line"><span>After verification, remaining COD</span><strong>${money(2800)}</strong></div><div class="error-text" data-error></div><button class="btn full mt" ${p?.status==='Verified'?'disabled':''}>Apply demo decision</button></form></div>`;}if(tab==='settlement')return `${heading('Courier / COD Settlement','Reconcile collected COD, fees and the actual payout.')}${t}<div class="stats">${stat('Gross collection',money(15000),'3 parcels','truck')}${stat('Courier charges',money(300),'Listed deductions','file')}${stat('Expected payout',money(14700),'Collection less fees','wallet')}${stat('Variance',money(50),'Must be resolved before posting','info')}</div>${table(['Order','Collected','Charges','Net'],[['AEL-0901',money(7000),money(120),money(6880)],['AEL-0902',money(4500),money(90),money(4410)],['AEL-0903',money(3500),money(90),money(3410)]])}<form class="card mt" data-form="settlement"><h3>Match bank receipt</h3><div class="field-grid">${field('Actual receipt','amount','14650','number','min="0" step="0.01" required')}${field('Bank reference','reference','','text','required placeholder="DEMO-BANK-REF"')}</div>${textarea('Reconciliation note','note')}<div class="error-text" data-error></div><button class="btn">Review reconciliation</button><p class="form-help">Unexplained differences cannot be silently posted.</p></form>`;return `${heading('Payments','Verification and settlement are independent.',exportBtn('payments'))}${t}${filterBar('payments','Search reference, order or method…')}<div data-filter-table="payments">${table(['Reference','Order','Method','Amount','Verification','Settlement',''],s.records.payments.filter(r=>!r.archived).map(p=>[p.id,p.order,E(p.method),money(p.amount),badge(p.status),badge(p.settlement,'outline'),edit('payments',p.id)]))}</div>`}
function courier(s){return `${heading('Courier Operations','Booking, delivery updates and exception handling.',link('COD settlement','/admin/payments/settlement','btn secondary'))}<div class="stats">${stat('To book',s.orders.filter(o=>o.courier==='Not booked').length,'Ready for eligibility review','box')}${stat('In transit',s.orders.filter(o=>o.status==='In Transit').length,'Dispatched parcels','truck')}${stat('Failed delivery',s.orders.filter(o=>o.status==='Failed Delivery').length,'Review before retry / return','info')}${stat('Integration','Demo only','No live API requests','settings')}</div>${table(['Order','Customer','Consignment','Status','Remaining COD',''],s.orders.map(o=>[o.id,E(o.customer),E(o.courier),badge(o.status),money(o.total-o.paid),recordActions(s,'orders',o.id)+button(o.courier==='Not booked'?'Preview booking':'Review','courier-book',`data-id="${o.id}"`,'btn small secondary')]))}<div class="notice mt">Booking does not mean dispatched or delivered. Failed deliveries do not automatically restock items or create refunds.</div>`}
function returns(s){return `${heading('Returns & Refunds','Receipt, inspection, restock and refund stay separate.',newBtn('returns','New return'))}${s.records.returns.filter(r=>!r.archived).map(r=>`<div class="card"><div class="between mb"><div><h3>${E(r.id)} · ${E(r.order)}</h3><p class="small muted">${E(r.product)} · ${r.qty} item</p></div>${badge(r.status)}</div><div class="stats">${stat('Return amount',money(r.amount),'Original paid amount in sample','wallet')}${stat('Inspection',r.status==='Inspection passed'?'Passed':'Pending','Physical condition','box')}${stat('Restock',r.restock,'Independent stock step','layers')}${stat('Refund',r.refund,'Payment execution separate','return')}</div><div class="flex" style="flex-wrap:wrap">${recordActions(s,'returns',r.id)}${button('Inspect return','inspect-return',`data-id="${r.id}"`,'btn secondary')}${button('Review restock','restock-return',`data-id="${r.id}" ${r.restock==='Completed'?'disabled':''}`,'btn secondary')}${button('Review refund','refund-review',`data-id="${r.id}"`,'btn')}</div></div>`).join('')}<div class="notice mt">Refund approval does not confirm a payout. Actual payment execution is a separate backend/provider step.</div>`}
const reportGroups=[['Sales & customers',['Sales','Orders','Products','Customers','Discounts','Coupons','Taxes']],['Stock & operations',['Inventory','Stock movements','Low stock','Purchases','Suppliers','Courier','Returns']],['Finance',['Payments','COD','Expenses','Accounts','Income','Profit / Loss']]];
const reportRows=[['AEL-0931','02 Sep','Delivered',6000,300,0,5700],['AEL-0932','07 Sep','Delivered',5000,200,0,4800],['AEL-0933','12 Sep','Partial return',4000,200,1500,2300],['AEL-0934','18 Sep','Delivered',3000,200,0,2800],['AEL-0935','24 Sep','Completed',2000,100,0,1900]];
export {reportRows};
function reports(s,type){const p=profitStatement(demoReport);if(!type)return `${heading('Reports Overview','Sales, operations and financial performance.',button('Print','print','','btn secondary'))}<div class="toolbar"><span class="small">Sample reporting period</span><strong class="small">01–30 Sep 2026</strong><span class="spacer"></span>${badge('BDT')}</div><div class="stats">${stat('Net sales',money(p.revenue),'Recognized sales','chart')}${stat('Gross profit',money(p.grossProfit),'After actual item cost','chart')}${stat('Net profit',money(p.netProfit),'After expenses','wallet')}${stat('Recognized orders',5,'Delivered / completed','bag')}</div><div class="module-grid">${reportGroups.map(([title,items])=>`<div class="module-card"><h3>${title}</h3>${items.map(label=>link(label+icon('chevron'),'/admin/reports/'+label.toLowerCase().replaceAll(' ','-').replace('/',''), 'list-link')).join('')}</div>`).join('')}</div><div class="notice mt">Advances and cash receipts are separate from recognized revenue. This report uses a fixed September sample.</div>`;const isProfit=type.startsWith('profit'),isSales=type==='sales';if(isProfit)return `${heading('Profit / Loss','01–30 Sep 2026 · Illustrative recognition basis',button('Print','print','','btn secondary')+exportBtn('profit'))}<div class="stats">${stat('Net revenue',money(p.revenue),'After discounts & refunds','chart')}${stat('Cost of goods sold',money(p.cogs),'Actual product cost','box')}${stat('Gross profit',money(p.grossProfit),'Revenue less COGS','chart')}${stat('Net profit',money(p.netProfit),'After expenses','wallet',true)}</div><div class="two-col"><div class="card"><h3>Profit statement</h3>${[['Gross sales',20000],['Discounts',-1000],['Sales refunds',-1500],['Net revenue',17500],['Cost of goods sold',-11000],['Gross profit',6500],['Courier expense',-800],['Gateway fees',-200],['Return handling',-300],['Operating expenses',-1200],['Net profit',4000]].map(([l,n])=>`<div class="status-line"><${['Net revenue','Gross profit','Net profit'].includes(l)?'strong':'span'}>${l}</${['Net revenue','Gross profit','Net profit'].includes(l)?'strong':'span'}><strong>${n<0?'−':''}${money(Math.abs(n))}</strong></div>`).join('')}</div><div class="stack"><div class="card"><h3>Product cost basis</h3><div class="summary-line">Delivered / sold item cost <strong>${money(12000)}</strong></div><div class="summary-line">Posted return reversal <strong>−${money(1000)}</strong></div><div class="summary-line total">Net COGS <strong>${money(11000)}</strong></div></div>${notice('Purchases affect stock. Only the cost of goods sold enters this profit statement. The sample has no delivery income or tax.')}</div></div>`;if(isSales)return `${heading('Sales Report','01–30 Sep 2026 · Recognition date',button('Print','print','','btn secondary')+exportBtn('sales'))}<div class="stats">${stat('Gross sales',money(20000))}${stat('Discounts',money(1000))}${stat('Refunds',money(1500))}${stat('Net sales',money(17500))}</div>${filterBar('sales','Search sample orders…')}<div data-filter-table="sales">${table(['Order','Date','Status','Gross','Discount','Refund','Net'],reportRows.map(r=>r.map((c,i)=>i===2?badge(c):i>=3?money(c):c)).concat([['<strong>Total</strong>','','',money(20000),money(1000),money(1500),'<strong>'+money(17500)+'</strong>']]))}</div><div class="notice mt">Net sales = gross sales − discounts − refunds. Advances and pending orders are excluded.</div>`;const title=type.replaceAll('-',' ').replace(/^./,c=>c.toUpperCase());let key=type==='stock-movements'?'movements':type==='low-stock'?'inventory':type;return `${heading(title+' Report','Filtered sample records · BDT',button('Print','print','','btn secondary')+exportBtn(key))}<div class="toolbar"><label class="small">Period</label><input type="date" value="2026-10-01" aria-label="Start date" style="max-width:170px"><input type="date" value="2026-10-07" aria-label="End date" style="max-width:170px">${button('Apply range','report-range','','btn small secondary')}</div>${genericReport(s,key)}<p class="form-help">Only sample records are shown. The reporting engine, live aggregation and Excel/PDF generation are later backend work. Browser print can save this view to PDF.</p>`}
function genericReport(s,key){const arr=key==='orders'?s.orders:key==='products'?s.products:key==='inventory'?s.products.flatMap(p=>p.variants.map(v=>({product:p.name,size:v.size,onHand:v.onHand,reserved:v.reserved,available:v.onHand-v.reserved}))):s.records[key];if(arr?.length){const keys=Object.keys(arr[0]).filter(k=>!['items','variants','image','description'].includes(k)).slice(0,7);return table(keys.map(k=>E(k.replace(/^./,c=>c.toUpperCase()))),arr.map(r=>keys.map(k=>E(r[k]))));}if(key==='accounts'||key==='income')return table(['Account','Available balance'],Object.entries(s.accounts).map(([a,b])=>[a,money(b)]));if(key==='taxes')return notice('No tax entries exist in the sample dataset. Tax configuration is available in Website Settings.');return notice('No sample entries for this report. Add or review records in the corresponding admin module.');}
function coupons(s){return `${heading('Coupons & Promotions','Offer rules, schedules and redemption limits.',link('Banners','/admin/banners','btn secondary')+newBtn('coupons','Create promotion'))}<div class="stats">${stat('Active',s.records.coupons.filter(x=>x.status==='Active').length)}${stat('Scheduled',s.records.coupons.filter(x=>x.status==='Scheduled').length)}${stat('Drafts',s.records.coupons.filter(x=>x.status==='Draft').length)}${stat('Redemptions',s.records.coupons.reduce((a,c)=>a+c.used,0))}</div>${filterBar('coupons','Search name or code…')}<div data-filter-table="coupons">${table(['Promotion','Method','Benefit','Usage','Status',''],s.records.coupons.filter(r=>!r.archived).map(c=>[`<strong>${E(c.id)}</strong><p class="small muted">${E(c.name)}</p>`,E(c.method),c.method==='Free shipping'?'Free shipping':c.value+'% off'+(c.cap?`<p class="small muted">Cap ${money(c.cap)}</p>`:''),c.used+' / '+c.limit,badge(c.status),edit('coupons',c.id,'Edit')]))}</div><div class="notice mt">Incompatible offers do not combine unless explicitly allowed. Drafts remain inactive.</div>`}
function content(s,id){if(id)return contentEditor(s,id);return `${heading('CMS Pages','Storefront pages and editorial content.',newBtn('pages','New page'))}${tabs([['content','Pages'],['banners','Homepage banners']], 'content','/admin/')}<div class="stats">${stat('Total pages',s.records.pages.length)}${stat('Published',s.records.pages.filter(x=>x.status==='Published').length)}${stat('Drafts',s.records.pages.filter(x=>x.status==='Draft').length)}</div>${filterBar('pages','Search pages…')}<div data-filter-table="pages">${table(['Page','Route','Status',''],s.records.pages.filter(r=>!r.archived).map(p=>[E(p.name),'/' +E(p.id),badge(p.status),recordActions(s,'pages',p.id)]))}</div><div class="notice mt">Draft preview and publishing remain distinct. All page states here are sample data.</div>`}
function audit(s){return `${heading('Audit Log','Actions performed in this preview session.',exportBtn('audit'))}${table(['Time','Actor','Action','Module',''],[...s.audit].reverse().map((a,i)=>[a.time,E(a.actor),E(a.action),E(a.module),button('View','audit-view',`data-index="${s.audit.length-1-i}"`,'btn small secondary')+button('Edit','audit-locked','disabled title="Audit history is append-only"','btn small secondary')+button('Delete','audit-locked','disabled title="Audit history is append-only"','btn small ghost')]))}`}
export function adminView(path,s){const [,root,section='overview',sub]=path.split('/');const role=s.previewRole||'Super Admin';if(!can(s,section))return `${heading('Role preview','This module is outside the selected role.')}<div class="card">${notice('This demonstrates the intended role boundary. Production permissions will be enforced on the server.')}${button('Return to Super Admin preview','reset-role','','btn mt')}</div>`;switch(section){case'owner-ai':return ownerAssistantView(s);case'welcome-popup':return popupEditor(s);case'reviews':return reviewsAdmin(s);case'overview':return dashboard(s);case'support':return inbox(s,sub);case'archive':return archiveView(s);case'orders':return orders(s,sub);case'manual':return manual(s);case'products':return products(s);case'inventory':return inventoryView(s,sub);case'purchases':return purchases(s);case'suppliers':return suppliers(s);case'customers':return customers(s,sub);case'accounts':return accounts(s,sub)+balanceControls(s);case'payments':return payments(s,sub);case'courier':return courier(s);case'returns':return returns(s);case'reports':return reports(s,sub);case'coupons':return coupons(s);case'banners':return bannerEditor(s);case'content':return content(s,sub);case'seo':return seoView(s,sub||'overview');case'team':return teamView(s,sub);case'audit':return audit(s);case'settings':return settingsView(s,sub||'general');default:return empty('Module not found','Choose a module from the sidebar.','/admin','Back to overview');}}
